using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using Jindan.Contracts;
using Jindan.Core;
using Jindan.Desktop.Contracts;
using Jindan.Infrastructure;

static class Program
{
    static readonly List<object> Results = [];
    static string Root = "";
    static void Check(bool condition, string detail = "Assertion failed") { if (!condition) throw new Exception(detail); }
    static async Task Case(string name, Func<Task> action) { try { await action(); Results.Add(new { name, pass = true }); Console.WriteLine("PASS " + name); } catch (Exception ex) { Results.Add(new { name, pass = false, error = ex.Message }); Console.WriteLine("FAIL " + name + " " + ex); } }
    static void Reject(Action action, params string[] codes) { try { action(); } catch (WorkspaceException ex) when (codes.Contains(ex.Code)) { return; } throw new Exception("Expected reject: " + string.Join(',', codes)); }
    static async Task RejectAsync(Func<Task> action, string code) { try { await action(); } catch (WorkspaceException ex) when (ex.Code == code) { return; } throw new Exception("Expected reject: " + code); }
    static T Native<T>(Func<T> action) { T result = default!; Exception? error = null; var thread = new Thread(() => { try { result = action(); } catch (Exception ex) { error = ex; } }); thread.SetApartmentState(ApartmentState.STA); thread.Start(); thread.Join(); if (error is not null) throw error; return result; }
    public static async Task<int> Main(string[] args)
    {
        var outputIndex = Array.IndexOf(args, "--output");
        Root = outputIndex >= 0 ? Path.GetFullPath(args[outputIndex + 1]) : Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "../../../../../artifacts/richtext70", Guid.NewGuid().ToString("N")));
        if (Directory.Exists(Root) && Directory.EnumerateFileSystemEntries(Root).Any()) throw new InvalidOperationException("Fresh output required.");
        Directory.CreateDirectory(Root);
        var text = "금회 조사 양식 · 아직 실측값 없음\nA<&> {literal} \\ 경로 😀\n두 번째 문단";
        string rtf = "";
        await Case("native Unicode Korean escaped braces slash emoji round trip and plain correspondence", () => { rtf = Native(() => { using var editor = new RichTextEditor70(); editor.Fill(text, ""); var captured = editor.CaptureFormatting(); File.WriteAllText(Path.Combine(Root, "generated-rtf.txt"), captured.Rtf); Check(captured.Text == text); return captured.Rtf; }); Check(RichTextRules70.PlainText(rtf) == text); return Task.CompletedTask; });
        string styled = "";
        await Case("bold italic underline strikeout size color background alignment bullet indentation survive native reopen", () => { styled = Native(() => { using var editor = new RichTextEditor70(); editor.Fill(text, ""); editor.Editor.Select(0, 2); editor.Editor.SelectionFont = new Font(editor.Editor.Font.FontFamily, 18, FontStyle.Bold | FontStyle.Italic | FontStyle.Underline | FontStyle.Strikeout); editor.Editor.SelectionColor = Color.Red; editor.Editor.SelectionBackColor = Color.Yellow; editor.Editor.SelectionAlignment = HorizontalAlignment.Center; editor.Editor.SelectionBullet = true; editor.Editor.SelectionIndent = 24; var saved = editor.CaptureFormatting(); File.WriteAllText(Path.Combine(Root, "styled-rtf.txt"), saved.Rtf); using var reopened = new RichTextEditor70(); reopened.Fill(saved.Text, saved.Rtf); reopened.Editor.Select(0, 2); Check(reopened.Editor.SelectionFont?.Style == (FontStyle.Bold | FontStyle.Italic | FontStyle.Underline | FontStyle.Strikeout)); Check(reopened.Editor.SelectionFont?.Size == 18 && reopened.Editor.SelectionColor.ToArgb() == Color.Red.ToArgb() && reopened.Editor.SelectionBackColor.ToArgb() == Color.Yellow.ToArgb()); Check(reopened.Editor.SelectionAlignment == HorizontalAlignment.Center && reopened.Editor.SelectionBullet && reopened.Editor.SelectionIndent == 24); return saved.Rtf; }); return Task.CompletedTask; });
        await Case("actual DPI120 font charset129 without ansicpg decodes exact bound Korean text", () => { const string value = "{\\rtf1\\ansi\\deff0\\nouicompat{\\fonttbl{\\f0\\fnil\\fcharset129 Korean;}}\\viewkind4\\uc1\\pard\\b\\f0\\fs18\\lang1042\\'bc\\'ad\\'bd\\'c4\\b0\\'b8\\'b8 \\'b9\\'d9\\'b2\\'d9\\'b4\\'c2 \\'c7\\'d5\\'bc\\'ba \\'c1\\'b6\\'bb\\'e7 \\'b8\\'de\\'b8\\'f0\\par}"; RichTextRules70.Validate(value, "서식만 바꾸는 합성 조사 메모"); return Task.CompletedTask; });
        await Case("font switch and scoped default font honor charset while unsafe content still rejects", () => { const string value = "{\\rtf1\\ansi\\deff1{\\fonttbl{\\f0\\fnil\\fcharset0 Latin;}{\\f1\\fnil\\fcharset129 Korean;}}\\'bc\\'ad{\\f0 ABC}\\'bd\\'c4\\par}"; RichTextRules70.Validate(value, "서ABC식"); Reject(() => RichTextRules70.Validate(value, "wrong"), "RICH_TEXT_MISMATCH"); return Task.CompletedTask; });
        await Case("formatting-only toolbar action raises change without changing plain text", () => { Native(() => { using var editor = new RichTextEditor70(); editor.Fill("조사 형식", ""); int changes = 0; editor.FormattingChanged += (_, _) => changes++; editor.Editor.SelectAll(); var bold = editor.Controls.OfType<FlowLayoutPanel>().Single().Controls.OfType<Button>().Single(b => b.Text == "굵게"); bold.PerformClick(); Check(changes > 0 && editor.IsEdited && editor.Editor.Text == "조사 형식"); Check(editor.CaptureFormatting().Rtf.Contains("\\b", StringComparison.Ordinal)); return 0; }); return Task.CompletedTask; });
        await Case("unchanged formatting action stays clean and duplicate notifications do not raise dirty", () => { Native(() => { using var editor = new RichTextEditor70(); editor.Fill("취소·동일 서식", ""); int changes = 0; editor.FormattingChanged += (_, _) => changes++; editor.Controls.OfType<FlowLayoutPanel>().Single().Controls.OfType<Button>().Single(b => b.Text == "왼쪽").PerformClick(); typeof(RichTextEditor70).GetMethod("NotifyChanged", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!.Invoke(editor, null); Check(!editor.IsEdited && changes == 0); return 0; }); return Task.CompletedTask; });
        await Case("literal old HTML stays literal; no browser interpretation", () => { const string html = "<b>이전 HTML</b><script>alert(1)</script>"; Native(() => { using var editor = new RichTextEditor70(); editor.Fill(html, ""); Check(editor.Editor.Text == html && RichTextRules70.PlainText(editor.CaptureFormatting().Rtf) == html); return 0; }); return Task.CompletedTask; });
        await Case("embedded picture object field binary file and unknown destination reject before native load", () => { foreach (var word in new[] { "pict", "object", "field", "bin", "file", "htmltag", "include", "unknown" }) { var bad = "{\\rtf1{\\*\\" + word + " x}body\\par}"; Reject(() => RichTextRules70.Validate(bad, "body"), "RICH_TEXT_FORMAT"); } Native(() => { using var editor = new RichTextEditor70(); editor.Fill("safe fallback", "{\\rtf1{\\object x}bad\\par}"); Check(editor.Editor.Text == "safe fallback"); return 0; }); return Task.CompletedTask; });
        await Case("unbalanced nested duplicate root oversized malformed and text mismatch reject", () => { foreach (var bad in new[] { "{\\rtf1 missing", "{\\rtf1 a}{\\rtf1 b}", "{\\rtf1\\u9999999?}", new string('{', 65) + "\\rtf1" + new string('}', 65), "{\\rtf1" + new string('x', 600001) + "}" }) Reject(() => RichTextRules70.Validate(bad, ""), "RICH_TEXT_FORMAT", "RICH_TEXT_MISMATCH"); Reject(() => RichTextRules70.Validate("{\\rtf1 old\\par}", "new"), "RICH_TEXT_MISMATCH"); return Task.CompletedTask; });

        var projects = new Jindan.Modules.Projects.Module().Schema; var board = new Jindan.Modules.Board.Module().Schema;
        using var workspace = new LocalWorkspace(Path.Combine(Root, "workspace")); workspace.RegisterSchema(projects); workspace.RegisterSchema(board);
        var actor = await workspace.BootstrapAsync("Synthetic rich owner", "rich-format-password-70", true);
        WorkRecord? project = null; WorkRecord? post = null;
        await Case("formatted project and board service save keep searchable content plus separate formatting", async () => { Check(styled.Length > 0, "Formatting generation must pass first"); var fields = new Dictionary<string, string>() { ["title"] = "Synthetic format", ["content"] = text, ["contentRtf"] = styled }; project = await workspace.SaveAsync(actor, new(null, "projects", null, 0, fields)); post = await workspace.SaveAsync(actor, new(null, "board", null, 0, fields)); Check((await workspace.ListAsync(actor, new RecordQuery("projects", Search: "금회 조사"))).Single().Id == project.Id && post.Fields["content"] == text); });
        await Case("query search uses authoritative text and excludes RTF font control metadata", async () => { Check((await workspace.ListAsync(actor, new RecordQuery("projects", Search: "fonttbl"))).Count == 0 && (await workspace.ListAsync(actor, new RecordQuery("board", Search: "colortbl"))).Count == 0); });
        await Case("service mismatched or unsafe RTF rejection leaves persisted bytes revision unchanged", async () => { var before = File.ReadAllBytes(Path.Combine(workspace.DataRoot, "workspace.json")); await RejectAsync(() => workspace.SaveAsync(actor, new(project!.Id, "projects", null, project.Revision, new(project.Fields) { ["contentRtf"] = "{\\rtf1 wrong\\par}" })), "RICH_TEXT_MISMATCH"); await RejectAsync(() => workspace.SaveAsync(actor, new(project!.Id, "projects", null, project.Revision, new(project.Fields) { ["contentRtf"] = "{\\rtf1{\\pict x}}" })), "RICH_TEXT_FORMAT"); Check(before.SequenceEqual(File.ReadAllBytes(Path.Combine(workspace.DataRoot, "workspace.json")))); });
        await Case("plain existing records remain optional and source text untouched", async () => { const string original = "<div>원래 문자 그대로</div>"; var plain = await workspace.SaveAsync(actor, new(null, "projects", null, 0, new() { ["title"] = "Unformatted", ["content"] = original })); Check(!plain.Fields.ContainsKey("contentRtf") && plain.Fields["content"] == original); });
        await Case("fresh local workspace reopening preserves exact formatting and plain content", async () => { using var reopened = new LocalWorkspace(workspace.DataRoot); reopened.RegisterSchema(projects); reopened.RegisterSchema(board); var identity = await reopened.LoginAsync(actor.DisplayName, "rich-format-password-70"); var current = (await reopened.ListAsync(identity, new RecordQuery("board"))).Single(); Check(current.Fields["contentRtf"] == styled && current.Fields["content"] == text); });
        await Case("board thread renders bounded formatting and hides the raw companion column", () => { Native(() => { using var doc = new Jindan.Modules.Board.BoardDocument(new Services(workspace, actor), board, new("rich-thread70", "board", null, actor.Id)); var render = typeof(Jindan.Modules.Board.BoardDocument).GetMethod("RenderThread", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!; render.Invoke(doc, new object[] { new[] { post! } }); var field = typeof(Jindan.Modules.Board.BoardDocument).GetField("thread", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!; var thread = (RichTextBox)field.GetValue(doc)!; var offset = thread.Text.IndexOf(text, StringComparison.Ordinal); Check(offset >= 0); thread.Select(offset, 2); Check(thread.SelectionFont?.Bold == true && thread.SelectionFont?.Size == 18); var grid = (DataGridView)typeof(RecordDocument).GetField("Grid", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!.GetValue(doc)!; Check(!grid.Columns["contentRtf"]!.Visible); return 0; }); return Task.CompletedTask; });
        await Case("Board module only uses shared UI formatting boundary without undeclared Core reference", () => { Check(!typeof(Jindan.Modules.Board.BoardDocument).Assembly.GetReferencedAssemblies().Any(a => a.Name == "Jindan.Core")); return Task.CompletedTask; });
        await Case("workspace ZIP export new-copy import rollback retain both fields; original never overwritten", async () => { var path = Path.Combine(Root, "formatted.zip"); await workspace.ExportAsync(actor, path); var preview = await workspace.PreviewImportAsync(actor, path); await workspace.ImportAsync(actor, preview, true); var copied = (await workspace.ListAsync(actor, new RecordQuery("board"))).Single(r => r.Id != post!.Id); Check(copied.Fields["contentRtf"] == styled && copied.Fields["content"] == text); await workspace.RollbackLastImportAsync(actor, true); Check((await workspace.ListAsync(actor, new RecordQuery("board"))).Single().Id == post!.Id); });
        await Case("board reply plain-text limit remains enforced with formatting", () => { var content = new string('a', 10001); Reject(() => DomainRules.ValidateFields(board, new() { ["title"] = "reply", ["parentId"] = "parent", ["content"] = content, ["contentRtf"] = "{\\rtf1 " + content + "\\par}" }), "VALIDATION"); return Task.CompletedTask; });
        var fail = Results.Count(r => !JsonSerializer.SerializeToElement(r).GetProperty("pass").GetBoolean());
        File.WriteAllText(Path.Combine(Root, "RESULT.json"), JsonSerializer.Serialize(new { schema = "native-richtext70/1", pass = Results.Count - fail, fail, tests = Results, loadedAssemblies = new[] { typeof(RichTextRules70).Assembly, typeof(RichTextEditor70).Assembly, typeof(Jindan.Modules.Projects.Module).Assembly, typeof(Jindan.Modules.Board.Module).Assembly, typeof(LocalWorkspace).Assembly }.Select(a => new { a.Location, sha256 = Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(a.Location))) }), nativeControlWithoutVisibleGui = true, noCompanyOrHancomApproval = true, reportReady = false, supervisorAccepted = false }, new JsonSerializerOptions() { WriteIndented = true }));
        Console.WriteLine($"RESULT pass={Results.Count - fail} fail={fail} output={Root}"); return fail == 0 ? 0 : 1;
    }
    sealed class Services(LocalWorkspace workspace, Identity actor) : IWorkspaceServices
    {
        public Identity Actor => actor; public IWorkspaceData Data => workspace; public IIdentityService Identities => workspace; public IAssetService Assets => workspace; public IReportService Reports => throw new NotSupportedException(); public ILayoutStore Layout => workspace; public string DataRoot => workspace.DataRoot;
    }
}
